        // configuration (Test 1, 2026-11-02: a by-hand Create Request started a run twice); a status start is the same Agreement Desk event.
        // A schedule start too [inferred cause]: on Test 1 (no Connect configuration) a From a Schedule workflow's publish answered
        // success but it stayed a draft, with or without an agent step (story-assets, 2026-11-04); on the lab account, which has
        // Connect, the same start went active (B10-S, lab a603e0ce). Connect is the likely difference, not yet proven.
        if (t.event || t.schedule)
            add('connect', sp.id);
        const onRequest = !!(t.request || t.on);
        if (onRequest) {
            add('app-access', sp.id);
            add('agreement-desk', sp.id);
            apps.desk = true;
        }
        let sf = false;
        walk(sp.steps, (s) => {
            if (s.sign && s.direct)
                add('in-session', sp.id);
            if (s.sign)
                add('ecf', sp.id);
            if (s.agent) {
                for (const id of ['agent-first', 'agents-plan', 'ai-controls', 'agent-region', 'app-access'])
                    add(id, sp.id);
                apps.agents = true;
            }
            if (s.salesforceRead || (s.generate && /salesforce/.test(String(s.generate))))
                sf = true;
            if (s.form)
                add('forms', sp.id);
            if (s.webRequest)
                add('web-request-apply', sp.id);
            if (s.verifyIdentity?.wallet)
                add('identity-wallet', sp.id);
            if (s.runPlaybook)
                add('run-playbook-select', sp.id);
            if ('status' in s)
                add('request-statuses', sp.id);
            if (s.createRequest) {
                add('app-access', sp.id);
                add('agreement-desk', sp.id);
                apps.desk = true;
            }
            if (onRequest && ['status', 'due', 'owner', 'changeTitle'].some((k) => k in s))
                add('desk-manage', sp.id);
        });
        const sfStart = t.api?.salesforce ?? t.link?.salesforce;
        if (sf || sfStart)
            for (const id of ['salesforce-install', 'salesforce-refresh', 'salesforce-health', 'salesforce-org'])
                add(id, sp.id);
