    if (o.agents)
        for (const id of ['agent-quota', 'agents-plan', 'ai-controls', 'agent-region', 'app-access'])
            add(id, '');
    if (o.agreementSearch)
        add('am-portfolio', '');
    if (o.clm)
        add('clm-publish', '');
    const CLM_NEEDS = {
        'clm-esign': ['sendForSignature', 'reviewAndSendForSignature', 'waitForSignature', 'cancelElectronicSignature'],
        'clm-tasks': ['approve', 'choice', 'editDocument', 'reviewData', 'updateInformation', 'chooseDocuments', 'chooseUsers', 'editForm', 'fillForm'],
        'clm-external-review': ['externalReview', 'sendForExternalReview', 'waitExternalReview'],
        'clm-ai': ['useDocusignAi'],
        'clm-party': ['addParty', 'editParty', 'findParty'],
        'clm-subworkflows': ['childWorkflow'],
    };
