        if ((o.clmSteps ?? []).some((k) => kinds.includes(k)))
            add(id, '');
    for (const id of o.tabOrder ?? [])
        add('tab-order', id);
    for (const id of o.sfEsign ?? [])
        add('sf-esign-layout', id);
    for (const id of o.notary ?? [])
        add('notary', id);
    for (const id of o.obligations ?? [])
        add('track-obligations', id);
    const access = needs.get('app-access');
    if (access) {
        const which = [apps.agents && 'Agent Studio for whoever creates the agents, and the agent shared with the group that uses it', apps.desk && 'Agreement Desk for request work', o.agreementSearch && 'Agreement Manager for agreement search'].filter(Boolean);
        if (which.length)
            access.why = `${access.why}: ${which.join('; ')}`;
    }
